package com.example.bandlink.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="blocks",uniqueConstraints=@UniqueConstraint(name="uk_block_pair",columnNames={"blocker_id","blocked_id"})) public class Block { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="blocker_id") private User blocker; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="blocked_id") private User blocked; @Column(nullable=false) private LocalDateTime createdAt; protected Block(){} public Block(User a,User b,LocalDateTime now){blocker=a;blocked=b;createdAt=now;} public Long getId(){return id;} public User getBlocker(){return blocker;} public User getBlocked(){return blocked;} }
